import{_ as e,c as r,o as t,ae as i}from"./chunks/framework.CHDT0Kbg.js";const h=JSON.parse('{"title":"Recorrido de funciones","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/features.md","filePath":"es/guide/features.md","lastUpdated":1795170900000}'),s={name:"es/guide/features.md"};function o(d,a,l,n,c,u){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="recorrido-de-funciones" tabindex="-1">Recorrido de funciones <a class="header-anchor" href="#recorrido-de-funciones" aria-label="Permalink to &quot;Recorrido de funciones&quot;">​</a></h1><p>Lo que más usarás, explicado en breve.</p><h2 id="navegacion-diaria" tabindex="-1">Navegación diaria <a class="header-anchor" href="#navegacion-diaria" aria-label="Permalink to &quot;Navegación diaria&quot;">​</a></h2><ul><li>Varias pestañas y ventanas: arrastrar, agrupar, plegar, silenciar y previsualizar.</li><li>La barra de direcciones sugiere primero los sitios conocidos y luego busca en la web.</li><li>Paleta de comandos (⌘K), búsqueda de pestañas (⌘⇧A), buscar en la página (⌘F) y lista de atajos en el menú del engranaje.</li></ul><h2 id="comodo-a-la-vista" tabindex="-1">Cómodo a la vista <a class="header-anchor" href="#comodo-a-la-vista" aria-label="Permalink to &quot;Cómodo a la vista&quot;">​</a></h2><ul><li>Tema: seguir el sistema, claro u oscuro. También puedes forzar páginas oscuras y cambiar de tema cada día.</li><li>Seis colores de acento: azul, violeta, turquesa, verde, naranja y rosa.</li><li>Barra de marcadores: siempre oculta, siempre visible o solo en la nueva pestaña.</li></ul><h2 id="anuncios-y-scripts" tabindex="-1">Anuncios y scripts <a class="header-anchor" href="#anuncios-y-scripts" aria-label="Permalink to &quot;Anuncios y scripts&quot;">​</a></h2><ul><li>El bloqueador admite suscripciones, reglas propias y lista de permitidos. Si falla una actualización, siguen rigiendo las reglas anteriores.</li><li>Los scripts de usuario (<code>.user.js</code>) se gestionan en Ajustes y se instalan al terminar la descarga.</li></ul><h2 id="videos-y-archivos" tabindex="-1">Vídeos y archivos <a class="header-anchor" href="#videos-y-archivos" aria-label="Permalink to &quot;Vídeos y archivos&quot;">​</a></h2><ul><li>Las descargas se pueden pausar, reanudar, cancelar y reintentar. Al terminar, muestra el archivo en Finder o ábrelo con la app relacionada.</li><li>El panel multimedia reconoce vídeos en la página y une las partes en un solo MP4.</li></ul><h2 id="atajos" tabindex="-1">Atajos <a class="header-anchor" href="#atajos" aria-label="Permalink to &quot;Atajos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Atajo</th><th>Acción</th></tr></thead><tbody><tr><td>⌘T / ⌘W</td><td>Nueva / cerrar pestaña</td></tr><tr><td>⌘L</td><td>Ir a la barra de direcciones</td></tr><tr><td>⌘F</td><td>Buscar en la página</td></tr><tr><td>⌘⇧N</td><td>Ventana privada</td></tr><tr><td>⌘K</td><td>Paleta de comandos</td></tr><tr><td>⌘⇧A</td><td>Buscar pestañas</td></tr><tr><td>⌘⇧R</td><td>Modo lectura</td></tr></tbody></table>',12)])])}const m=e(s,[["render",o]]);export{h as __pageData,m as default};
